// Webhook body -> one item per ACCEPTED row, validated before it reaches SQL.
// Expected POST body (matches server/temporal/classification_workflow.py
// ClassificationBatchPipeline._call(PERSIST_PATH, ...) EXACTLY - not owned by this packet,
// read there if this ever needs re-verifying):
//   { "run_key": "...", "batch_index": 0, "classifier_version": "...", "items": [ <accepted rows> ] }
// GAP-031 (2026-08-26): items that passed the Temporal review gate additionally carry
//   { "gate_outcome": "accepted", "adjudication": { decision_id, actor, decision, reason, source } }
// Straight-through (unsupervised or high-confidence, never gated) items carry neither field.
const body = $input.first().json.body || $input.first().json || {};
const items = body.items || [];
if (!Array.isArray(items) || items.length === 0) {
  throw new Error('persist-results: body.items must be a non-empty array of ACCEPTED rows');
}
if (!body.run_key || body.batch_index === undefined || body.batch_index === null || !body.classifier_version) {
  throw new Error('persist-results: body.run_key, body.batch_index, body.classifier_version are required');
}
const nowIso = new Date().toISOString();
const VALID_DECISIONS = ['approve', 'correct'];

function toIso(v) {
  if (v === undefined || v === null || v === '') return null;
  const d = typeof v === 'number' ? new Date(v) : new Date(v);
  if (isNaN(d.getTime())) throw new Error('persist-results: unparseable timestamp ' + JSON.stringify(v));
  return d.toISOString();
}

return items.map((it, i) => {
  if (it.gate_outcome && it.gate_outcome !== 'accepted') {
    throw new Error('persist-results: item ' + i + ' is not accepted (gate_outcome=' +
                    it.gate_outcome + '). needs_review/rejected/pending rows do NOT persist here.');
  }
  // GAP-031: item identity precedence mirrors ClassificationBatchPipeline._item_key exactly
  // (chunk_id > record_id > record_ref); this table's item-identity column is record_ref.
  const recordRef = it.chunk_id || it.record_id || it.record_ref;
  if (!recordRef) {
    throw new Error('persist-results: item ' + i + ' has none of chunk_id/record_id/record_ref');
  }
  const messageText = it.text || it.message_text;
  if (!messageText) {
    throw new Error('persist-results: item ' + i + ' is missing text/message_text');
  }

  const adj = it.adjudication || null;
  if (adj) {
    if (!(adj.decision_id && adj.actor && adj.reason && adj.source)) {
      throw new Error('persist-results: item ' + i + ' adjudication is missing decision_id/actor/reason/source');
    }
    if (!VALID_DECISIONS.includes(adj.decision)) {
      throw new Error('persist-results: item ' + i + ' adjudication.decision must be approve or correct, got ' +
                      JSON.stringify(adj.decision));
    }
  }

  return { json: {
    run_key: String(body.run_key),
    batch_index: Number(body.batch_index),
    classifier_version: String(body.classifier_version),
    conversation_key: it.conversation_key || null,
    seq: it.seq != null ? Number(it.seq) : null,
    record_ref: String(recordRef),
    occurred_at: toIso(it.occurred_at),
    message_text: String(messageText),
    labels: Array.isArray(it.labels) ? it.labels.map(String) : [],
    sentiment: it.sentiment || null,
    severity: it.severity != null ? Number(it.severity) : null,
    summary: it.summary || null,
    judge_verdict: it.judge_verdict || null,
    judge_confidence: it.judge_confidence != null ? Number(it.judge_confidence) : null,
    judge_model: it.judge_model || null,
    classify_model: it.classify_model || null,
    review_state: adj ? 'reviewed' : 'unreviewed',
    // GAP-031 adjudication provenance (sql/0034) - NULL for non-gated (straight-through) items.
    decision_id: adj ? String(adj.decision_id) : null,
    actor: adj ? String(adj.actor) : null,
    decision: adj ? String(adj.decision) : null,
    reason: adj ? String(adj.reason) : null,
    source: adj ? String(adj.source) : null,
    adjudicated_at: adj ? nowIso : null,
    activity_name: 'n8n.persist.results',
  }};
});

// Activity result: what landed, under which run/batch/classifier version, and how many
// of the inserted rows carried a GAP-031 adjudication (vs. straight-through accepts).
const rows = $input.all().map(i => i.json);
const src = $('Normalize + Validate Accepted Rows').all().map(i => i.json);
const nowIso = new Date().toISOString();
const insertedIds = new Set(rows.filter(r => r && r.id).map(r => r.id));
return [{ json: {
  activity_name: 'n8n.persist.results',
  status: 'completed',
  run_key: src.length ? src[0].run_key : null,
  batch_index: src.length ? src[0].batch_index : null,
  classifier_version: src.length ? src[0].classifier_version : null,
  submitted_count: src.length,
  inserted_count: insertedIds.size,
  skipped_existing_count: src.length - insertedIds.size,
  adjudicated_count: src.filter(r => r.decision_id).length,
  persisted_at_iso: nowIso,
  rows: rows,
}}];
